<h1><?= te('Assignments, equipment and transport') ?></h1><p class="sub"><?= te('Selected project operations. Create scheduled routes in Travel first.') ?></p>
<div class="card scroll"><h2><?= te('Assignments') ?></h2><table><tr><th><?= te('Worker') ?></th><th><?= te('Trade / shift / supervisor') ?></th><th><?= te('Update') ?></th></tr><?php foreach($crew as $c): ?><tr><td><?= e($c['full_name']) ?></td><td><?= e(($c['trade'] ?: t('Trade not set')).' · '.($c['shift_label'] ?: t('shift not set')).' · '.($c['supervisor'] ?: t('no supervisor'))) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="offboard"><input type="hidden" name="placement_id" value="<?= (int)$c['id'] ?>"><button class="btn ghost sm"><?= te('Complete assignment') ?></button></form></td></tr><?php endforeach; ?></table></div>
<div class="grid g2"><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="assignment"><h2><?= te('Set assignment') ?></h2><label><?= te('Worker') ?></label><select name="placement_id"><?php foreach($crew as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><label><?= te('Trade / job title') ?></label><input name="trade" required maxlength="190"><label><?= te('Shift') ?></label><input name="shift_label" maxlength="190"><label><?= te('Supervisor') ?></label><select name="supervisor_id"><option value=""><?= te('Unassigned') ?></option><?php foreach($supervisors as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Save assignment') ?></button></form>
<form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="passenger"><h2><?= te('Assign pickup route') ?></h2><label><?= te('Worker') ?></label><select name="placement_id"><?php foreach($crew as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><label><?= te('Run / driver / seats') ?></label><select name="run_id"><?php foreach($runs as $r): ?><option value="<?= (int)$r['id'] ?>"><?= e($r['runs_on'].' '.$r['depart_time'].' · '.$r['driver'].' · '.$r['seats'].' seats') ?></option><?php endforeach; ?></select><label><?= te('Pickup stop') ?></label><input name="pickup_stop" required maxlength="190"><button class="btn"><?= te('Assign passenger') ?></button></form></div>
<div class="card"><h2><?= te('Passenger manifests') ?></h2><?php foreach($passengers as $r): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="attendance"><input type="hidden" name="passenger_id" value="<?= (int)$r['id'] ?>"><span><?= e($r['runs_on'].' · '.$r['driver'].' · '.$r['full_name'].' · '.$r['pickup_stop'].' · '.$r['attendance']) ?></span><select name="attendance"><option value="scheduled"><?= te('scheduled') ?></option><option value="boarded"><?= te('boarded') ?></option><option value="absent"><?= te('absent') ?></option></select><button class="btn sm"><?= te('Update') ?></button></form><?php endforeach; ?></div>
<div class="grid g2"><?php if(can('admin')): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="asset"><h2><?= te('Add equipment') ?></h2><label><?= te('Name') ?></label><input name="name" required maxlength="190"><label><?= te('Unique asset tag') ?></label><input name="asset_tag" required maxlength="120"><label><?= te('Equipment owner') ?></label><select name="owner_type"><option value="agency"><?= te('Agency') ?></option><option value="client"><?= te('Client') ?></option></select><label><?= te('Client owner · when applicable') ?></label><select name="owner_client_id"><option value=""><?= te('Select client') ?></option><?php foreach($clients as $client): ?><option value="<?= (int)$client['id'] ?>"><?= e($client['name']) ?></option><?php endforeach; ?></select><label><?= te('Serial number') ?></label><input name="serial_number" maxlength="190"><button class="btn"><?= te('Add asset') ?></button></form><?php endif; ?>
<form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="issue"><h2><?= te('Issue equipment') ?></h2><label><?= te('Worker') ?></label><select name="placement_id"><?php foreach($crew as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><label><?= te('Asset') ?></label><select name="equipment_id"><?php foreach($assets as $a): ?><option value="<?= (int)$a['id'] ?>"><?= e($a['name'].' · '.$a['asset_tag']) ?></option><?php endforeach; ?></select><label><?= te('Condition') ?></label><select name="issue_condition"><option value="good"><?= te('Good') ?></option><option value="worn"><?= te('Worn') ?></option><option value="damaged"><?= te('Damaged') ?></option></select><p class="muted"><?= te('Only available items, inspected and belonging to the agency or this client, are listed.') ?> <a href="/assets"><?= te('All assets') ?></a></p><button class="btn"><?= te('Issue asset') ?></button></form></div>
<div class="card"><h2><?= te('Outstanding equipment') ?></h2><?php foreach($issues as $i): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="return"><input type="hidden" name="issue_id" value="<?= (int)$i['id'] ?>"><span><?= e($i['full_name'].' · '.$i['name'].' · '.$i['asset_tag']) ?></span><select name="return_condition"><option value="good"><?= te('Good') ?></option><option value="worn"><?= te('Worn') ?></option><option value="damaged"><?= te('Damaged') ?></option><option value="lost"><?= te('Lost') ?></option></select><input name="return_note" placeholder="<?= te('Note · required if damaged or lost') ?>" maxlength="255"><button class="btn sm"><?= te('Record return') ?></button></form><?php endforeach; ?></div>
<?php if(can('recruiter')): ?><div class="grid g2"><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="wave"><h2><?= te('Create deployment wave') ?></h2><label><?= te('Name') ?></label><input name="name" required><label><?= te('Arrival date') ?></label><input name="arrival_date" type="date" required><label><?= te('Target headcount') ?></label><input name="headcount_target" type="number" min="0"><label><?= te('Wave supervisor') ?></label><select name="supervisor_id"><option value=""><?= te('Unassigned') ?></option><?php foreach($supervisors as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Create wave') ?></button></form><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="wave_member"><h2><?= te('Assign worker to wave') ?></h2><label><?= te('Worker') ?></label><select name="placement_id"><?php foreach($crew as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><label><?= te('Wave') ?></label><select name="wave_id"><?php foreach($waves as $w): ?><option value="<?= (int)$w['id'] ?>"><?= e($w['name'].' · '.$w['arrival_date'].' · '.$w['assigned'].'/'.$w['headcount_target']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Assign to wave') ?></button></form></div><?php endif; ?><div class="card"><h2><?= te('Deployment waves') ?></h2><?php foreach($waves as $w): ?><p><?= e($w['name'].' · '.$w['arrival_date'].' · '.$w['supervisor'].' · '.$w['assigned'].'/'.$w['headcount_target']) ?></p><?php endforeach; ?></div>
<div class="card"><h2><?= te('Department assignment') ?></h2><form method="post" class="row"><?= csrf_field() ?><input name="do" value="department_assignment" type="hidden"><select name="placement_id"><?php foreach($crew as $person): ?><option value="<?= (int)$person['id'] ?>"><?= e($person['full_name']) ?></option><?php endforeach; ?></select><select name="department_id"><?php foreach($departments as $department): ?><option value="<?= (int)$department['id'] ?>"><?= e($department['name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Assign department') ?></button></form><p class="muted"><?= te('Outstanding equipment blocks operational closeout. It does not automatically withhold earned wages; final-pay review must follow applicable law.') ?></p></div>
